 "กี่โมง": [
  "what time?",
  "yeah, right; as if; sure you will (sarcastic retort) (slang)",
  "@@note:Literally \"what time?\" — but on its own, กี่โมง is a popular sarcastic comeback, like \"yeah, right\" or \"sure you will.\" You use it to shoot down something you find totally unrealistic or hard to believe.\n\nSay a friend swears he’ll wake up at 5am tomorrow to go running. You know it’ll never happen, so you just reply กี่โมง gèe-mohng — a dry \"Sure you will.\"\n\nOr a friend keeps insisting some gorgeous woman is secretly into him. You raise an eyebrow and hit him with กี่โมงแล้ว gèe-mohng láew (\"what time is it already?\") — basically \"wake up\" / \"keep dreaming.\""
 ],
